import fs from 'fs';
import path from 'path';
import { MANIFEST_FILE } from './constants.js';
export function getUrlSafeFileName(filePath) {
    const { name } = path.parse(filePath);
    return encodeURIComponent(`${name}.js`);
}
// Strips ANSI color codes out of strings because we don't want to pass them to the browser
export function stripAnsiColorCodes(stringWithColorCodes) {
    if (!stringWithColorCodes) {
        return null;
    }
    return stringWithColorCodes.replace(
    // eslint-disable-next-line no-control-regex
    /[\u001b][[]*([0-9]{1,4};?)*[m]/g, '');
}
export function loadManifest(outputDir, output) {
    try {
        return JSON.parse(fs
            .readFileSync(path.join(outputDir, `${output}-${MANIFEST_FILE}`))
            .toString());
    }
    catch (e) {
        return {};
    }
}
export function buildSourceId(appConfig, extensionConfig) {
    if (appConfig.uid && extensionConfig.data.uid) {
        return `${appConfig.uid}::${extensionConfig.data.uid}`;
    }
    return null;
}
export function isNodeModule(filepath) {
    if (!filepath) {
        return false;
    }
    const directory = path.parse(filepath).dir;
    return directory.includes('node_modules');
}
/**
 * Check if a given file is within the extension path
 */
export function isExtensionFile(filepath, extensionPath) {
    if (!filepath) {
        return false;
    }
    try {
        const absoluteFilePath = fs.realpathSync(filepath);
        const absoluteExtensionDirPath = fs.realpathSync(extensionPath);
        const relativePath = path.relative(absoluteExtensionDirPath, absoluteFilePath);
        return !relativePath.startsWith('..') && !path.isAbsolute(relativePath);
    }
    catch (e) {
        console.log(`Error checking if ${filepath} is in extension path: ${e}`);
        // If there's an error, we can't determine if the file is in the extension path, so return false.
        return false;
    }
}
export class UnhandledPlatformVersionError extends Error {
    constructor(platformVersion) {
        super(`Unsupported platform version "${platformVersion}"`);
    }
}
export function throwUnhandledPlatformVersionError(platformVersion) {
    throw new UnhandledPlatformVersionError(platformVersion);
}
export function isUnifiedAppConfig(config) {
    return 'unified' in config && config.unified === true;
}
export function extractAllowedUrls(appConfig) {
    if (!appConfig || !('allowedUrls' in appConfig) || !appConfig.allowedUrls) {
        return [];
    }
    return appConfig.allowedUrls;
}
function simpleHash(input) {
    let hash = 0;
    for (let i = 0; i < input.length; i++) {
        const char = input.charCodeAt(i);
        hash = (hash * 31 + char) % 2147483647;
    }
    return Math.abs(hash).toString(16);
}
/**
 * This function generates a deterministic hash from any number of arguments
 * Arrays and objects are stringified to ensure it works for all types.
 * Uses the same simple hash algorithm as the browser version for consistency.
 */
export function generateHash(...args) {
    try {
        // First make sure all the values are strings
        const normalizedArgs = args.map((arg) => {
            if (Array.isArray(arg)) {
                return [...arg].sort().join('-');
            }
            if (arg && typeof arg === 'object') {
                return JSON.stringify(arg, Object.keys(arg).sort());
            }
            return String(arg);
        });
        // Return the hash of the joined strings.
        const input = [...normalizedArgs].join('::');
        return simpleHash(input);
    }
    catch (e) {
        console.error('Error generating hash: ', e);
        // Just return an empty string if anything goes wrong.
        return '';
    }
}
/**
 * Matches the reference ID generation in ui-extensibility's dataDependencyResolver.ts (generateSearchReferenceId).
 */
export function generateCrmSearchReferenceId(config) {
    const parts = [
        config.objectType,
        config.query ?? '',
        JSON.stringify(config.filterGroups ?? []),
        [...(config.properties ?? [])].sort().join('-'),
        JSON.stringify(config.sorts ?? []),
        String(config.limit ?? ''),
    ];
    return simpleHash(`CrmSearch::${parts.join('::')}`);
}
/**
 * Check if a given URL is an image (of a type we support)
 */
export function isImage(url) {
    return /\.(png|jpg|jpeg|gif|svg|webp|avif|raw|url|inline)$/.test(url);
}
/**
 * Returns true for developer test accounts, sandboxes, and any account with a
 * `parentAccountId`. Returns false for `STANDARD` and for `APP_DEVELOPER` —
 * the latter is the parent portal where private-app user tokens can actually
 * be minted, so the fetch path must run there.
 */
export async function isTestOrSandboxAccount(accountId) {
    /*
     * getConfigAccountIfExists throws a HubSpotConfigError when no config file
     * exists at all (e.g. in CI). Treat that as "not a test/sandbox" so the
     * caller falls through to the normal fetch path rather than crashing.
     */
    let account;
    try {
        const { getConfigAccountIfExists } = await import('@hubspot/local-dev-lib/config');
        const { HUBSPOT_ACCOUNT_TYPES } = await import('@hubspot/local-dev-lib/constants/config');
        account = getConfigAccountIfExists(accountId);
        if (!account || account.accountType === HUBSPOT_ACCOUNT_TYPES.STANDARD) {
            return false;
        }
        return (Boolean(account.parentAccountId) ||
            account.accountType === HUBSPOT_ACCOUNT_TYPES.DEVELOPER_TEST ||
            account.accountType === HUBSPOT_ACCOUNT_TYPES.DEVELOPMENT_SANDBOX ||
            account.accountType === HUBSPOT_ACCOUNT_TYPES.STANDARD_SANDBOX);
    }
    catch {
        return false;
    }
}
/**
 * We need to warn developers when certain configuration files are present in the extension source, as these files will be ignored during the build process.
 * It's sure to miss some setups and that's ok!
 * No security relies on this, and these files already wouldn't have the expected impact in extensions.
 */
const IGNORED_CONFIG_PATTERNS = {
    'Vite config': /^vite\.config\.[mc]?[tj]s$/,
    'PostCSS config': /^(postcss\.config\.[mc]?[tj]s|\.postcssrc(\.[mc]?[tj]s|\.ya?ml|\.json)?)$/,
    'Tailwind config': /^tailwind\.config\.[mc]?[tj]s$/,
    'Environment file': /^\.env(\.[^.]+)*$/,
};
export function warnAboutIgnoredConfigFiles(root, logger = console) {
    let files;
    try {
        files = fs.readdirSync(root);
    }
    catch {
        return;
    }
    for (const [label, pattern] of Object.entries(IGNORED_CONFIG_PATTERNS)) {
        const found = files.filter((f) => pattern.test(f));
        if (found.length > 0) {
            logger.warn(`${label} found in extension source (${found.join(', ')}) and ignored: ` +
                `extension builds do not load configuration from extension source.`);
        }
    }
}
